import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity, TextInput } from 'react-native';
import { useNavigation } from '@react-navigation/native';

const Header = () => {
  const navigation = useNavigation<any>();

  return (
    <View style={styles.container}>
      {/* Top Row: Brand & Icons */}
      <View style={styles.topRow}>
        <Text style={styles.brand}>Menha Boutique</Text>
        <View style={styles.iconsRow}>
            <TouchableOpacity style={styles.iconButton} onPress={() => navigation.navigate('Login')}>
              <Text style={{fontSize: 20}}>👤</Text>
            </TouchableOpacity>
            <TouchableOpacity style={styles.iconButton} onPress={() => navigation.navigate('Cart')}>
              {/* Placeholder for Cart Icon */}
              <View style={styles.cartBadge}>
                <Text style={styles.cartBadgeText}>0</Text>
              </View>
              <Text style={{fontSize: 20}}>🛒</Text>
            </TouchableOpacity>
        </View>
      </View>
      
      {/* Search Bar */}
      <View style={styles.searchContainer}>
        <TextInput 
          style={styles.input} 
          placeholder="Search for products..." 
          placeholderTextColor="#888"
        />
        <View style={styles.searchIcon}>
            <Text>🔍</Text>
        </View>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingHorizontal: 15,
    paddingTop: 10, // StatusBar handled by SafeAreaView
    paddingBottom: 10,
    backgroundColor: '#fff',
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  topRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 10,
  },
  iconsRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  brand: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#E53935', // Brand Color
  },
  iconButton: {
    padding: 5,
    position: 'relative',
  },
  cartBadge: {
    position: 'absolute',
    top: 0,
    right: 0,
    backgroundColor: 'red',
    borderRadius: 8,
    width: 16,
    height: 16,
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 1,
  },
  cartBadgeText: {
    color: '#fff',
    fontSize: 10,
    fontWeight: 'bold',
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#f1f2f6',
    borderRadius: 8,
    paddingHorizontal: 10,
    height: 40,
  },
  input: {
    flex: 1,
    height: '100%',
    marginLeft: 5,
  },
  searchIcon: {
    padding: 5,
  }
});

export default Header;
